package com.steven.assets.service.srpp.settings;
import com.steven.assets.dto.SrppClaudeAuthDto;import com.sun.net.httpserver.HttpServer;import java.net.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.concurrent.atomic.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import static org.assertj.core.api.Assertions.*;
class SrppClaudeAuthLocalTest {
 @TempDir Path temp;HttpServer server;SrppClaudeAuthLocal client;AtomicInteger count=new AtomicInteger();AtomicReference<String> request=new AtomicReference<>();String reply="{\"code\":\"AUTH_INVALID_CODE\",\"message\":\"SECRET_NATIVE_CODE\",\"execution\":null}";int status=400;
 @BeforeEach void setup()throws Exception{Path token=temp.resolve("token");Files.writeString(token,"t".repeat(43));server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/",x->{count.incrementAndGet();request.set(x.getRequestMethod()+" "+x.getRequestURI().getPath()+" "+new String(x.getRequestBody().readAllBytes(),StandardCharsets.UTF_8));assertThat(x.getRequestHeaders().getFirst("Authorization")).isEqualTo("Bearer "+"t".repeat(43));byte[] bytes=reply.getBytes(StandardCharsets.UTF_8);x.getResponseHeaders().set("Content-Type","application/json");x.sendResponseHeaders(status,bytes.length);x.getResponseBody().write(bytes);x.close();});server.start();client=new SrppClaudeAuthLocal(URI.create("http://127.0.0.1:"+server.getAddress().getPort()),token);}
 @AfterEach void stop(){server.stop(0);}
 @Test void exactAuthPostNoRetryAndProviderErrorIsSanitized(){assertThatThrownBy(()->client.call("complete",SrppClaudeAuthDto.parse("{\"ownerId\":7,\"sessionBinding\":\"binding\",\"flowId\":\"flow\",\"code\":\"private#state\"}"))).isInstanceOfSatisfying(SrppClaudeAuthProblem.class,e->{assertThat(e.code()).isEqualTo("AUTH_INVALID_CODE");assertThat(e.getMessage()).doesNotContain("SECRET_NATIVE_CODE","private#state");});assertThat(count.get()).isEqualTo(1);assertThat(request.get()).startsWith("POST /auth/claude/complete ");}
 @Test void unknownErrorAndOversizedResponseFailClosed(){reply="{\"code\":\"SECRET_PROVIDER_ERROR\",\"message\":\"secret\",\"execution\":null}";assertThatThrownBy(()->client.call("state",SrppClaudeAuthDto.parse("{}"))).isInstanceOfSatisfying(SrppClaudeAuthProblem.class,e->assertThat(e.code()).isEqualTo("AUTH_FAILED"));reply="a".repeat(20000);assertThatThrownBy(()->client.call("state",SrppClaudeAuthDto.parse("{}"))).hasMessageNotContaining("aaaaa");assertThat(count.get()).isEqualTo(2);}
 @Test void productionPortConstructsWithInjectedTokenPath(){try(var context=new org.springframework.context.annotation.AnnotationConfigApplicationContext()){context.getEnvironment().getPropertySources().addFirst(new org.springframework.core.env.MapPropertySource("test",java.util.Map.of("srpp.settings.ai-token-file",temp.resolve("token").toString())));context.register(SrppClaudeAuthLocal.class);context.refresh();assertThat(context.getBean(SrppClaudeAuthPort.class)).isInstanceOf(SrppClaudeAuthLocal.class);}}
 @Test void invalidActionNeverSendsRequest(){assertThatThrownBy(()->client.call("../usage",SrppClaudeAuthDto.parse("{}"))).isInstanceOf(SrppClaudeAuthProblem.class);assertThat(count.get()).isZero();}
}
